<template>
  <div class="shell">
    <aside class="rail">
      <div class="brandmark">
        <div class="coin"><img :src="emblemSrc" alt="Stima Sacco"></div>
        <div class="word"><b>STIMA SACCO</b><span>Loan Application </span></div>
      </div>
      <div class="ledger">
        <p class="lg-title">Application flow</p>
        <div v-for="item in ledgerSteps" :key="item.id" class="lg-item" :class="ledgerClass(item)">
          <span class="lg-dot"></span><span class="lg-label">{{ item.label }}</span>
        </div>
      </div>
      <div class="testdata">
        <b>Demo data</b>
        Any name + ID looks up a member, except:<br>
        &bull; ID <code>00000000</code> &rarr; not found<br>
        &bull; ID <code>10000002</code> &rarr; ineligible member<br>
        &bull; Amount ending <code>.13</code> &rarr; one retry, then succeeds<br>
        &bull; Development Loan, amount a multiple of <code>100,000</code> &rarr; rejected<br>
        &bull; PIN <code>1234</code> at Verify Identity
      </div>
    </aside>

    <main class="device">
      <div class="topbar">
        <div class="row">
          <button class="back-btn" title="Back" :hidden="!canGoBack" @click="goBack">&#8592;</button>
          <div style="flex:1; min-width:0;">
            <div class="title">{{ screenMeta[current].title }}</div>
            <div class="subtitle" v-html="screenMeta[current].sub"></div>
          </div>
          <button class="reset-btn" @click="reset">&#8635; Restart demo</button>
        </div>
        <div class="progress-track"><div class="progress-fill" :style="{ width: progress + '%' }"></div></div>
      </div>

      <div class="content">
        <section v-if="current === 'home'" class="screen active">
          <div class="home-hero">
            <img class="full-logo" src="data:image/png;base64," alt="Stima Sacco — towards a prosperous future together">
            <h1>Loan Application</h1>
            <p>Fast, secure loan applications at the counter</p>
            <button class="btn btn-primary" @click="nav('identify')">Loan Application</button>
          </div>
          <div class="home-footer">Powered by Stima Sacco &bull; Member data protected end-to-end</div>
        </section>

        <section v-if="current === 'identify'" class="screen active">
          <p class="eyebrow">Step 1</p><h2 class="h-title">Member Identification</h2>
          <p class="h-desc">Enter the member's agreed identification details to look them up with the SACCO/CBS.</p>
          <div class="field"><label>Full Name</label><input v-model.trim="form.name" type="text" autocomplete="off" placeholder="e.g. Grace Mutua"></div>
          <div class="field"><label>ID Number</label><input v-model.trim="form.idNumber" type="text" autocomplete="off" inputmode="numeric" placeholder="e.g. 30112233"></div>
          <div v-if="errors.identify" class="error-banner">{{ errors.identify }}</div>
          <button class="btn btn-primary" :disabled="loading.identify" @click="lookupMember"><span v-if="loading.identify" class="spinner"></span>{{ loading.identify ? 'Working…' : 'Continue' }}</button>
        </section>

        <section v-if="current === 'member'" class="screen active">
          <p class="eyebrow">Step 2</p><h2 class="h-title">Member Details</h2>
          <div class="card">
            <div class="kv"><span class="k">Name</span><span class="v">{{ member?.fullName || '—' }}</span></div>
            <div class="kv"><span class="k">ID</span><span class="v">{{ member?.idNumber || '—' }}</span></div>
            <div class="kv"><span class="k">Member No.</span><span class="v mono">{{ member?.memberNumber || '—' }}</span></div>
          </div>
          <div v-if="errors.member" class="error-banner">{{ errors.member }}</div>
          <button class="btn btn-primary" :disabled="loading.member || eligibilityBlocked" @click="checkEligibility"><span v-if="loading.member" class="spinner"></span>{{ loading.member ? 'Working…' : 'Check Loan Eligibility' }}</button>
        </section>

        <section v-if="current === 'products'" class="screen active">
          <p class="eyebrow">Step 3</p><h2 class="h-title">Eligible Loan Products</h2><p class="h-desc">Select a product to continue.</p>
          <div v-if="products.length" class="card-list">
            <div v-for="p in products" :key="p.productCode" class="card clickable product-row" @click="selectProduct(p)">
              <div><div class="pname">{{ p.productName }}</div><div class="pmeta">Up to KES {{ fmt(p.maxAmount) }} &nbsp;&middot;&nbsp; {{ p.interestRate }}% p.a.</div></div><div class="chev">&#8250;</div>
            </div>
          </div>
          <div v-else class="warn-banner">No eligible loan products are available for this member.</div>
        </section>

        <section v-if="current === 'type'" class="screen active">
          <p class="eyebrow">Step 4</p><h2 class="h-title">Select Loan Type</h2><p class="h-desc">Product: {{ selectedProduct?.productName || '—' }}</p>
          <div class="stack">
            <div class="card type-card clickable" @click="chooseLoanType('GENERAL_SELF_GUARANTEE')"><div class="ticon">&#9998;</div><b>General / Self-Guarantee Loan</b><span>Secured against the member's own savings and shares &mdash; no guarantors needed.</span></div>
            <div class="card type-card clickable" @click="chooseLoanType('GUARANTOR')"><div class="ticon">&#128101;</div><b>Guarantor Loan</b><span>Requires approval from a SACCO-configured number of eligible guarantors.</span></div>
          </div>
        </section>

        <section v-if="current === 'auth'" class="screen active">
          <p class="eyebrow">Step 5</p><h2 class="h-title">Verify Your Identity</h2><p class="h-desc">For security, confirm it's you before entering a loan amount.</p>
          <div v-if="errors.auth" class="error-banner">{{ errors.auth }}</div>
          <div class="auth-grid">
            <button class="btn btn-gold" :disabled="loading.auth" @click="authenticateBiometric"><span v-if="loading.auth" class="spinner"></span>{{ loading.auth ? 'Working…' : '🔒 Use Biometric' }}</button>
            <button class="btn btn-outline" @click="showPin=true">Enter PIN</button>
          </div>
          <p class="pin-note">Demo PIN is <code>1234</code></p>
        </section>

        <section v-if="current === 'amount'" class="screen active">
          <p class="eyebrow">Step 6</p><h2 class="h-title">Enter Loan Amount</h2>
          <div class="amount-hint"><div><div class="amt-label">Maximum qualifying amount</div><div class="amt-val">KES {{ fmt(selectedProduct?.maxAmount || 0) }}</div></div></div>
          <div class="field"><label>Amount</label><div class="amount-input-wrap"><span class="cur">KES</span><input v-model="form.amount" type="text" inputmode="decimal" placeholder="0.00"></div></div>
          <div v-if="errors.amount" class="error-banner" v-html="errors.amount"></div>
          <button class="btn btn-primary" :disabled="loading.amount" @click="continueAmount"><span v-if="loading.amount" class="spinner"></span>{{ loading.amount ? 'Working…' : (loanType === 'GUARANTOR' ? 'Find Guarantors' : 'Submit Application') }}</button>
        </section>

        <section v-if="current === 'guarantors'" class="screen active">
          <p class="eyebrow">Step 7</p><h2 class="h-title">Guarantor Approval</h2>
          <div class="req-banner"><span>Approvals required</span><span class="count">{{ requiredApprovals }} of {{ guarantors.length }}</span></div>
          <div v-if="errors.guarantors" class="error-banner" v-html="errors.guarantors"></div>
          <div class="card-list">
            <div v-for="g in guarantors" :key="g.guarantorId" class="card guarantor-row">
              <div class="g-avatar">{{ initials(g.fullName) }}</div><div class="g-info"><div class="g-name">{{ g.fullName }}</div><div class="g-phone">{{ g.maskedPhoneNumber }}</div><div class="g-status" :class="statusClass(g)">{{ statusText(g) }}</div></div>
              <div class="g-action"><button class="btn btn-outline btn-sm" :disabled="g.status === 'APPROVED' || g.status === 'REJECTED' || !!g.requestId" @click="sendGuarantorRequest(g)">{{ actionLabel(g) }}</button></div>
            </div>
          </div>
          <button class="btn btn-primary" :disabled="loading.guarantors || approvedCount < requiredApprovals" @click="submitGuarantor"><span v-if="loading.guarantors" class="spinner"></span>{{ loading.guarantors ? 'Working…' : 'Submit Application' }}</button>
        </section>

        <section v-if="current === 'result'" class="screen active">
          <div class="result-wrap">
            <div class="result-icon" :class="lastResult?.status === 'APPROVED' ? 'ok' : 'no'">{{ lastResult?.status === 'APPROVED' ? '✓' : (lastResult ? '✕' : '!') }}</div>
            <div class="result-status" :class="lastResult?.status === 'APPROVED' ? 'ok' : 'no'">{{ lastResult?.status === 'APPROVED' ? 'Application Approved' : (lastResult ? 'Application Rejected' : 'No result received from SACCO/CBS.') }}</div>
            <div v-if="lastResult?.status === 'APPROVED'" class="result-ref">Reference: {{ lastResult.referenceNumber }}</div>
            <div v-if="lastResult?.status !== 'APPROVED' && lastResult?.reason" class="result-reason">{{ lastResult.reason }}</div>
            <div v-if="lastResult?.duplicate" class="warn-banner">This application was already submitted &mdash; showing the existing reference/status.</div>
          </div>
          <div class="spacer"></div><button class="btn btn-primary" @click="done">Done</button>
        </section>
      </div>
    </main>
  </div>

  <div class="toast" :class="{ show: showToastClass }">{{ toast }}</div>

  <div v-if="showPin" style="display:flex; position:fixed; inset:0; background:rgba(10,20,10,0.45); z-index:60; align-items:center; justify-content:center; padding:16px;">
    <div style="background:var(--surface); border-radius:16px; padding:22px; width:100%; max-width:300px; box-shadow:var(--shadow);">
      <h3 style="margin:0 0 4px; font-size:16px;">Enter PIN</h3><p style="margin:0 0 14px; font-size:12.5px; color:var(--text-secondary);">4-digit PIN</p>
      <input v-model="pin" @keyup.enter="confirmPin" type="password" maxlength="4" inputmode="numeric" placeholder="••••" style="text-align:center; letter-spacing:6px; font-size:19px; font-family:'JetBrains Mono';">
      <div style="min-height:18px; margin-top:8px; font-size:12px; color:var(--error); font-weight:600;">{{ pinError }}</div>
      <div style="display:flex; gap:9px; margin-top:6px;"><button class="btn btn-ghost" style="width:auto; flex:1;" @click="showPin=false">Cancel</button><button class="btn btn-primary" style="width:auto; flex:1;" @click="confirmPin">Confirm</button></div>
    </div>
  </div>
</template>

<script>
import { computed, reactive, ref } from 'vue';

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));
const javaHashCode = (str) => { let h=0; for(let i=0;i<str.length;i++) h=(Math.imul(h,31)+str.charCodeAt(i))|0; return h; };
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0,v=c==='x'?r:(r&0x3|0x8);return v.toString(16);});

export default {
  name: 'StimaSaccoLoanApplication',
  setup() {
    const emblemSrc = 'data:image/png;base64,';
    const current = ref('home');
    const historyStack = ref([]);
    const form = reactive({ name:'', idNumber:'', amount:'' });
    const member = ref(null), eligibility = ref(null), selectedProduct = ref(null), loanType = ref(null);
    const guarantors = ref([]), requiredApprovals = ref(0), lastResult = ref(null);
    const correlationId = ref(null);
    const errors = reactive({identify:'',member:'',auth:'',amount:'',guarantors:''});
    const loading = reactive({identify:false,member:false,auth:false,amount:false,guarantors:false});
    const showPin = ref(false), pin = ref(''), pinError = ref('');
    const toast = ref(''), toastVisible = ref(false);
    let toastTimer;

    const screenMeta = {
      home:{title:'Loan Application',sub:'Fast, secure loan applications at the counter'},
      identify:{title:'Member Identification',sub:'LOP-002 / LOP-003'}, member:{title:'Member Details',sub:'LOP-004 &ndash; LOP-006'},
      products:{title:'Eligible Loan Products',sub:'LOP-007'}, type:{title:'Select Loan Type',sub:'LOP-008'}, auth:{title:'Verify Your Identity',sub:'Security checkpoint'},
      amount:{title:'Enter Loan Amount',sub:'LOP-009 / LOP-010'}, guarantors:{title:'Guarantor Approval',sub:'LOP-012 &ndash; LOP-015'}, result:{title:'Application Result',sub:'LOP-011 / LOP-016'}
    };
    const ledgerSteps = [
      {id:'identify',label:'Identify member'},{id:'member',label:'Confirm eligibility'},{id:'products',label:'Choose product'},{id:'type',label:'Choose loan type'},
      {id:'auth',label:'Verify identity'},{id:'amount',label:'Enter amount'},{id:'guarantors',label:'Guarantor approval',conditional:true},{id:'result',label:'Decision'}
    ];
    const order = ['home','identify','member','products','type','auth','amount','guarantors','result'];
    const progress = computed(()=>Math.round(order.indexOf(current.value)/(order.length-1)*100));
    const canGoBack = computed(()=>current.value !== 'home' && historyStack.value.length>0);
    const products = computed(()=>eligibility.value?.eligibleProducts || []);
    const approvedCount = computed(()=>guarantors.value.filter(g=>g.status==='APPROVED').length);
    const eligibilityBlocked = ref(false);

    function nav(id,push=true) { if(push && current.value!==id) historyStack.value.push(current.value); current.value=id; window.scrollTo({top:0,behavior:'smooth'}); }
    function goBack() { if(historyStack.value.length) nav(historyStack.value.pop(),false); }
    function clearError(key) { errors[key]=''; }
    function showToast(msg) { toast.value=msg; toastVisible.value=true; clearTimeout(toastTimer); toastTimer=setTimeout(()=>toastVisible.value=false,2600); }
    function fmt(n) { return Number(n||0).toLocaleString(undefined,{maximumFractionDigits:0}); }
    function initials(name) { return name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase(); }
    function ledgerClass(item) { const idx=order.indexOf(item.id), cur=order.indexOf(current.value); const c={}; if(item.conditional && loanType.value!=='GUARANTOR' && current.value!=='guarantors') c.skip=true; if(idx<cur || (idx===cur && current.value==='result')) c.done=true; else if(idEqual(item.id,current.value)) c.current=true; return c; }
    function idEqual(a,b) { return a===b; }

    async function lookupMember() {
      clearError('identify'); if(!form.name || !form.idNumber) { errors.identify='Please enter both Name and ID.'; return; }
      loading.identify=true; try { await delay(700); if(form.idNumber==='00000000') throw new Error('No member found matching the supplied details.');
        const x=Math.abs(javaHashCode(form.idNumber)%90000); member.value={fullName:form.name,idNumber:form.idNumber,memberNumber:'M'+(10000+x)}; nav('member');
      } catch(e) { errors.identify=e.message; showToast(e.message); } finally { loading.identify=false; }
    }
    async function checkEligibility() {
      clearError('member'); loading.member=true; try { await delay(700);
        if(member.value?.memberNumber?.endsWith('13')) { eligibilityBlocked.value=true; errors.member='User cannot apply for loan. Reason: Member has an existing loan in arrears.'; return; }
        eligibility.value={eligible:true,eligibleProducts:[{productCode:'LP-GEN',productName:'General Loan',maxAmount:200000,interestRate:12},{productCode:'LP-DEV',productName:'Development Loan',maxAmount:500000,interestRate:11.5},{productCode:'LP-EMG',productName:'Emergency Loan',maxAmount:50000,interestRate:10}]}; nav('products');
      } catch(e) { errors.member=e.message; } finally { loading.member=false; }
    }
    function selectProduct(p) { selectedProduct.value=p; nav('type'); }
    function chooseLoanType(type) { loanType.value=type; correlationId.value=null; nav('auth'); }
    async function authenticateBiometric() { loading.auth=true; clearError('auth'); await delay(550); loading.auth=false; nav('amount'); }
    function confirmPin() { pinError.value=''; if(!/^\d{4}$/.test(pin.value)) { pinError.value='PIN must be 4 digits.'; return; } if(pin.value==='1234') { showPin.value=false; pin.value=''; nav('amount'); } else pinError.value='Incorrect PIN. Please try again.'; }
    async function continueAmount() {
      clearError('amount'); const amount=Number(String(form.amount).replace(/,/g,''));
      if(!form.amount || !Number.isFinite(amount) || amount<=0) { errors.amount='Please enter a valid amount greater than zero.'; return; }
      if(amount>selectedProduct.value.maxAmount) { errors.amount=`Amount exceeds the maximum qualifying amount of KES ${fmt(selectedProduct.value.maxAmount)}.`; return; }
      if(!correlationId.value) correlationId.value=uuid();
      loading.amount=true; try {
        if(loanType.value==='GUARANTOR') { guarantors.value=[{guarantorId:'G001',fullName:'Jane Wanjiku',maskedPhoneNumber:'07XX XXX 214',status:'PENDING',requestId:null},{guarantorId:'G002',fullName:'Peter Otieno',maskedPhoneNumber:'07XX XXX 559',status:'PENDING',requestId:null},{guarantorId:'G003',fullName:'Susan Achieng',maskedPhoneNumber:'07XX XXX 219',status:'PENDING',requestId:null}]; requiredApprovals.value=2; nav('guarantors'); return; }
        const result=await submitApplication('GENERAL_SELF_GUARANTEE',null,amount); lastResult.value=result; nav('result');
      } catch(e) { errors.amount=e.message+' You can retry &ndash; this will not create a duplicate application.'; } finally { loading.amount=false; }
    }
    function statusText(g) { if(g.status==='APPROVED') return 'Approved'; if(g.status==='REJECTED') return 'Rejected'; if(g.requestId) return 'Pending guarantor response…'; return 'Not sent'; }
    function statusClass(g) { if(g.status==='APPROVED') return 'approved'; if(g.status==='REJECTED') return 'rejected'; if(g.requestId) return 'waiting'; return 'pending'; }
    function actionLabel(g) { if(g.status==='APPROVED') return 'Approved'; if(g.status==='REJECTED') return 'Rejected'; if(g.requestId) return 'Pending…'; return 'Send OTP/Link'; }
    async function sendGuarantorRequest(g) { clearError('guarantors'); try { await delay(700); g.requestId=correlationId.value+'-'+Date.now(); setTimeout(()=>{g.status=g.maskedPhoneNumber.endsWith('214')?'REJECTED':'APPROVED'; if(g.status==='REJECTED') errors.guarantors=`${g.fullName} declined the guarantor request.`;},1500); } catch(e) { errors.guarantors=e.message; } }
    async function submitGuarantor() { clearError('guarantors'); loading.guarantors=true; try { const ids=guarantors.value.filter(g=>g.status==='APPROVED').map(g=>g.guarantorId); const result=await submitApplication('GUARANTOR',ids,Number(form.amount)); lastResult.value=result; nav('result'); } catch(e) { errors.guarantors=e.message+' You can retry &ndash; this will not create a duplicate application.'; } finally { loading.guarantors=false; } }
    const submissionResults=new Map(), submissionAttempts=new Map();
    async function submitApplication(type,approvedIds,amount) { await delay(700); const cid=correlationId.value; if(submissionResults.has(cid)) return {...submissionResults.get(cid),duplicate:true}; const attempt=(submissionAttempts.get(cid)||0)+1; submissionAttempts.set(cid,attempt); if(attempt===1 && Math.round(amount*100)%100===13) throw new Error('Request timed out contacting SACCO/CBS. Please retry.'); const rejected=amount%100000===0 && selectedProduct.value.productCode==='LP-DEV'; const result=rejected?{status:'REJECTED',reason:'Requested amount exceeds affordability limit for this product.',referenceNumber:null,duplicate:false}:{status:'APPROVED',reason:null,referenceNumber:'STIMA-'+(Date.now()%1000000),duplicate:false}; submissionResults.set(cid,result); return result; }
    function done() { historyStack.value=['home']; nav('products',false); }
    function reset() { Object.assign(form,{name:'',idNumber:'',amount:''}); member.value=null; eligibility.value=null; selectedProduct.value=null; loanType.value=null; guarantors.value=[]; requiredApprovals.value=0; lastResult.value=null; correlationId.value=null; eligibilityBlocked.value=false; Object.keys(errors).forEach(k=>errors[k]=''); Object.keys(loading).forEach(k=>loading[k]=false); historyStack.value=[]; current.value='home'; showPin.value=false; pin.value=''; pinError.value=''; showToast('Demo state reset'); }
    const showToastClass = computed(()=>toastVisible.value);
    return { emblemSrc,current,historyStack,form,member,products,selectedProduct,loanType,guarantors,requiredApprovals,lastResult,errors,loading,showPin,pin,pinError,toast,showToastClass,screenMeta,ledgerSteps,progress,canGoBack,approvedCount,eligibilityBlocked,nav,goBack,lookupMember,checkEligibility,selectProduct,chooseLoanType,authenticateBiometric,confirmPin,continueAmount,initials,statusText,statusClass,actionLabel,sendGuarantorRequest,submitGuarantor,done,reset,fmt,ledgerClass };
  }
};
</script>

<style>

  :root{
    /* Stima Sacco brand palette, sampled from the official logo */
    --primary:#2D2F93;        /* Stima navy (the "Y" mark / wordmark ink) */
    --primary-light:#4E51B8;
    --primary-dark:#171852;
    --accent:#D3AC65;         /* USHIRIKA banner gold */
    --brand-red:#EE1E27;      /* lightning-bolt red */
    --brand-yellow:#FFD400;   /* sunburst yellow */
    --error:#EE1E27;
    --success:#1E7A3D;
    --background:#F5F6FA;
    --surface:#FFFFFF;
    --text-primary:#1C1B1F;
    --text-secondary:#5B5E74;
    --divider:#E4E5F0;
    --white:#FFFFFF;
    --radius:16px;
    --shadow: 0 1px 2px rgba(23,24,82,0.07), 0 8px 24px -8px rgba(23,24,82,0.20);
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;}
  body{
    min-height:100vh;
    background:
      radial-gradient(1200px 700px at 15% -10%, rgba(45,47,147,0.14), transparent 60%),
      radial-gradient(1000px 700px at 100% 110%, rgba(211,172,101,0.16), transparent 55%),
      var(--background);
    font-family:'Inter',system-ui,sans-serif;
    color:var(--text-primary);
    display:flex;
    align-items:flex-start;
    justify-content:center;
    padding:36px 16px 60px;
  
  }
  h1,h2,h3,.display{font-family:'Sora',system-ui,sans-serif;}
  .mono{font-family:'JetBrains Mono',monospace;}

  .shell{
    width:100%;
    max-width:980px;
    display:grid;
    grid-template-columns:220px minmax(0,460px);
    gap:28px;
    align-items:start;
  }
  @media (max-width:860px){
    .shell{grid-template-columns:1fr; max-width:460px;}
    .rail{order:2;}
    .device{order:1;}
  }

  /* --- Left rail: brand + step ledger --- */
  .rail{
    position:sticky; top:36px;
    padding-top:6px;
  }
  .brandmark{
    display:flex; align-items:center; gap:11px; margin-bottom:22px;
  }
  .brandmark .coin{
    width:44px;height:44px;border-radius:50%;
    background:var(--surface);
    display:flex;align-items:center;justify-content:center;
    box-shadow: 0 0 0 1.5px var(--divider), var(--shadow);
    flex:none; padding:5px;
  }
  .brandmark .coin img{width:100%; height:100%; object-fit:contain;}
  .brandmark .word{line-height:1.15;}
  .brandmark .word b{display:block; font-family:'Sora'; font-weight:700; font-size:15.5px; letter-spacing:.2px;}
  .brandmark .word span{display:block; font-size:11.5px; color:var(--text-secondary); letter-spacing:.3px;}

  .ledger{
    background:var(--surface);
    border:1px solid var(--divider);
    border-radius:14px;
    padding:16px 16px 14px;
    box-shadow:var(--shadow);
  }
  .ledger .lg-title{
    font-size:10.5px; text-transform:uppercase; letter-spacing:1.4px;
    color:var(--text-secondary); font-weight:600; margin:0 0 12px 2px;
  }
  .lg-item{
    position:relative; padding:0 0 18px 26px;
  }
  .lg-item:last-child{padding-bottom:0;}
  .lg-item::before{ /* connecting line */
    content:''; position:absolute; left:8px; top:20px; bottom:-2px; width:1.5px;
    background:var(--divider);
  }
  .lg-item:last-child::before{display:none;}
  .lg-dot{
    position:absolute; left:0; top:1px; width:17px;height:17px;border-radius:50%;
    border:2px solid var(--divider); background:var(--surface);
    display:flex;align-items:center;justify-content:center;
    font-size:9px; color:transparent; font-weight:700; transition:all .25s ease;
  }
  .lg-item.done .lg-dot{ background:var(--primary); border-color:var(--primary); color:var(--white); }
