/* =========================================================
   POLISHED CARD DESIGN — STIMA SACCO
   ========================================================= */

:root {
  --card-radius: 22px;
  --card-shadow: 0 18px 50px -24px rgba(20, 55, 24, .28);
  --card-shadow-hover: 0 24px 65px -28px rgba(20, 55, 24, .34);
}

/* Main application card */
.screen {
  position: relative;
  overflow: hidden;
  border-radius: var(--card-radius);
  background:
    radial-gradient(circle at 100% 0%, rgba(242,183,5,.10), transparent 30%),
    linear-gradient(145deg, #ffffff 0%, #fbfdf9 100%);
  border: 1px solid rgba(27,94,32,.10);
  box-shadow: var(--card-shadow);
  padding: 30px;
  isolation: isolate;
}

/* Decorative green/gold glow */
.screen::before {
  content: "";
  position: absolute;
  width: 190px;
  height: 190px;
  right: -95px;
  top: -95px;
  border-radius: 50%;
  background: rgba(242,183,5,.12);
  pointer-events: none;
  z-index: -1;
}

.screen::after {
  content: "";
  position: absolute;
  width: 130px;
  height: 130px;
  left: -75px;
  bottom: -75px;
  border-radius: 50%;
  background: rgba(76,140,74,.08);
  pointer-events: none;
  z-index: -1;
}

/* Typography */
.screen .eyebrow {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(27,94,32,.08);
  color: var(--primary);
  font-size: 10px;
  letter-spacing: 1.4px;
  margin-bottom: 8px;
}

.screen .h-title {
  font-size: clamp(21px, 2vw, 28px);
  letter-spacing: -.35px;
}

.screen .h-desc {
  max-width: 620px;
}

/* Inputs feel more premium */
.screen input[type="text"],
.screen input[type="number"],
.screen input[type="password"],
.screen input[type="tel"] {
  min-height: 48px;
  border-radius: 13px;
  background: rgba(248,250,247,.9);
  border-color: #dce5da;
  box-shadow: inset 0 1px 1px rgba(0,0,0,.025);
}

.screen input:hover {
  border-color: rgba(76,140,74,.45);
}

.screen input:focus {
  border-color: var(--primary-light);
  box-shadow: 0 0 0 4px rgba(76,140,74,.10);
}

/* Product / guarantor cards */
.screen .card-list {
  gap: 12px;
}

.screen .clickable,
.screen .product-card,
.screen .guarantor-card,
.screen .approval-card {
  border-radius: 16px;
  transition:
    transform .18s ease,
    border-color .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}

.screen .clickable:hover,
.screen .product-card:hover,
.screen .guarantor-card:hover {
  transform: translateY(-2px);
  border-color: rgba(27,94,32,.42);
  box-shadow: 0 10px 28px -18px rgba(27,94,32,.5);
}

/* Selected states */
.screen .product-card.selected,
.screen .guarantor-card.selected {
  border-color: var(--primary);
  background:
    linear-gradient(135deg, rgba(27,94,32,.075), rgba(242,183,5,.045));
  box-shadow:
    0 0 0 1px rgba(27,94,32,.08),
    0 12px 30px -20px rgba(27,94,32,.38);
}

/* Make selection indicators attractive */
.screen .radio,
.screen .checkbox {
  width: 27px;
  height: 27px;
  border-radius: 50%;
  transition: .18s ease;
}

.screen .selected .radio,
.screen .selected .checkbox {
  box-shadow: 0 4px 12px -5px rgba(27,94,32,.65);
}

/* Guarantor avatar */
.screen .avatar,
.screen .g-avatar {
  box-shadow: 0 7px 18px -9px rgba(27,94,32,.7);
}

/* Amount highlight */
.screen .amount-hint {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  box-shadow: 0 10px 28px -20px rgba(27,94,32,.35);
}

.screen .amount-hint::after {
  content: "KES";
  position: absolute;
  right: 14px;
  bottom: 9px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
  color: rgba(27,94,32,.25);
}

/* Buttons */
.screen .btn,
.screen .primary-btn {
  min-height: 48px;
  border-radius: 13px;
  position: relative;
  overflow: hidden;
}

.screen .btn-primary,
.screen .primary-btn {
  background:
    linear-gradient(135deg, var(--primary) 0%, #2f7b35 100%);
  box-shadow:
    0 10px 24px -10px rgba(27,94,32,.62),
    inset 0 1px 0 rgba(255,255,255,.14);
}

.screen .btn-primary:hover,
.screen .primary-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow:
    0 14px 28px -11px rgba(27,94,32,.68),
    inset 0 1px 0 rgba(255,255,255,.16);
}

/* Gold CTA */
.screen .btn-gold {
  background: linear-gradient(135deg, #f2b705 0%, #ffc928 100%);
  box-shadow: 0 10px 24px -10px rgba(242,183,5,.65);
}

/* Result state */
.screen .result-wrap {
  padding-top: 24px;
}

.screen .result-icon {
  width: 78px;
  height: 78px;
  font-size: 34px;
  box-shadow:
    0 0 0 10px rgba(76,140,74,.07),
    0 18px 35px -14px rgba(27,94,32,.45);
}

.screen .result-ref {
  padding: 11px 18px;
  border-radius: 12px;
  box-shadow: 0 8px 20px -16px rgba(0,0,0,.35);
}

/* Info banners */
.screen .req-banner,
.screen .warn-banner,
.screen .error-banner {
  border-radius: 14px;
  box-shadow: 0 8px 20px -18px rgba(0,0,0,.25);
}

/* Mobile polish */
@media (max-width: 700px) {
  .screen {
    border-radius: 18px;
    padding: 20px 16px;
    box-shadow: 0 14px 38px -25px rgba(20,55,24,.28);
  }

  .screen::before {
    width: 130px;
    height: 130px;
    right: -65px;
    top: -65px;
  }

  .screen .h-title {
    font-size: 21px;
  }
}

@media (max-width: 420px) {
  .screen {
    border-radius: 16px;
    padding: 18px 14px;
  }

  .screen .product-card,
  .screen .guarantor-card {
    padding: 14px;
  }
}


/* =========================================================
   FULL-PAGE CARD + RESPONSIVE LAYOUT
   Desktop: card fills the available page.
   Mobile: card becomes a natural full-width flow.
   ========================================================= */

html,
body,
#app {
  width: 100%;
  min-width: 100%;
  min-height: 100%;
  margin: 0;
}

.page {
  width: 100%;
  min-width: 100%;
  min-height: 100vh;
  height: 100vh;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.shell {
  width: 100%;
  min-width: 0;
  min-height: 100vh;
  height: 100vh;
  margin: 0;
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: 0;
}

.device {
  width: calc(100% - 30px);
  min-width: 0;
  height: 100vh;
  min-height: 100vh;
  max-width: none;
  border-radius: 20px;
  border: 1px solid var(--divider);
  box-shadow: none;
}
.content {
  width: 100%;
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
  overflow: auto;
}

/* The actual step/card fills the desktop content area */
.screen {
  width: 100%;
  min-width: 0;
  max-width: none;
  min-height: calc(100vh - 125px);
  height: auto;
  box-sizing: border-box;
  margin: 0;
}

/* Don't artificially constrain the main card on wide displays */
@media (min-width: 901px) {
  .content {
    padding: 32px;
  }

  .screen {
    min-height: calc(100vh - 125px);
    display: flex;
    flex-direction: column;
  }

  .screen > .spacer {
    flex: 1;
  }
}

/* Medium screens */
@media (max-width: 900px) and (min-width: 701px) {
  .shell {
    grid-template-columns: 220px minmax(0, 1fr);
  }

  .content {
    padding: 24px;
  }

  .screen {
    min-height: calc(100vh - 110px);
  }
}

/* Mobile */
@media (max-width: 700px) {
  html,
  body,
  #app {
    min-height: 100%;
  }

  .page {
    height: auto;
    min-height: 100vh;
  }

  .shell {
    display: block;
    width: 100%;
    min-height: 100vh;
    height: auto;
  }

  .rail {
    display: none;
  }

  .device {
    width: 100%;
    height: auto;
    min-height: 100vh;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }

  .content {
    width: 100%;
    height: auto;
    min-height: calc(100vh - 70px);
    padding: 14px;
    overflow: visible;
  }

  .screen {
    width: 100%;
    min-height: calc(100vh - 100px);
    height: auto;
    margin: 0;
    border-radius: 18px;
    padding: 20px 16px;
  }
}

/* Small phones */
@media (max-width: 420px) {
  .content {
    padding: 10px;
  }

  .screen {
    min-height: calc(100vh - 90px);
    border-radius: 15px;
    padding: 17px 13px;
  }
}

/* Very short desktop screens: allow scrolling rather than clipping */
@media (min-width: 701px) and (max-height: 700px) {
  .device,
  .page,
  .shell {
    height: auto;
    min-height: 100vh;
  }

  .content {
    overflow: visible;
  }

  .screen {
    min-height: calc(100vh - 110px);
  }
}

